/* From Uiverse.io by felipesntr  - Tags:  */
.__UIV_SCOPE__ button {
  color: rgb(53, 188, 250);
  padding: 1em 2em 1em 2em;
  border: 2px solid rgb(53, 188, 250);
  border-radius: 0 1em 1em 1em;
  position: relative;
  overflow: hidden;
  transition: 0.3s;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
}

.__UIV_SCOPE__ button:hover {
  border: 2px solid rgb(75, 228, 157);
}

.__UIV_SCOPE__ button span {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: rgb(75, 228, 157);
  transition: ease-in-out 0.3s;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1em;
}

.__UIV_SCOPE__ button span svg {
  width: 1.1em;
  height: 1.1em;
  margin-right: 0.5em;
}

.__UIV_SCOPE__ button:hover span {
  left: 0%;
}
